package it.financemanager.infrastructure.security;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import it.financemanager.application.port.out.TokenPort;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Date;@Component public class JwtAdapter implements TokenPort{private final JwtProperties p;private final SecretKey key;public JwtAdapter(JwtProperties p){this.p=p;key=Keys.hmacShaKeyFor(p.secret().getBytes(StandardCharsets.UTF_8));}public String generate(String s){Instant n=Instant.now();return Jwts.builder().subject(s).issuedAt(Date.from(n)).expiration(Date.from(n.plus(p.expiration()))).signWith(key).compact();}public String subject(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}public long expiresInSeconds(){return p.expiration().toSeconds();}}
